"""Reproduce the synthetic config examples; no real host or credential inputs are accepted."""
import argparse
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def config_example_sources():
    return {
        'machines.example.yaml': '''# Generated by tools/make_fixtures.py; synthetic inventory with no secret values.
# Inline secret values are rejected by box-binder verify-config.
version: 1

defaults:
  auth_mode: jwt              # jwt | ccg-native | ccg-mint | oauth-broker
  box_sub_type: enterprise    # enterprise | user
  remote_name: box
  root_folder_id: "0"         # Box folder URL tail; "0" = service-account root
  rclone_min_version: "1.71.0"
  config_dir: /etc/box-binder
  health_interval: "*:0/15"   # systemd OnCalendar; every 15 min
  mint_interval_min: 45       # ccg-mint only: re-mint before the 60-min expiry
  impersonate_user_id: ""     # optional: as-user (needs App + Enterprise access)

secrets:
  # Only WHERE to read from — never the value. `source` selects the resolver.
  source: env                 # env | file | op | vault | aws-ssm
  jwt_config_ref: BOX_BINDER_JWT_CONFIG       # env var / op:// path holding config.json content
  client_id_ref: BOX_BINDER_CLIENT_ID
  client_secret_ref: BOX_BINDER_CLIENT_SECRET
  box_subject_id_ref: BOX_BINDER_ENTERPRISE_ID
  rclone_config_pass_ref: BOX_BINDER_RCLONE_PASS   # only if you fall back to an encrypted conf

hosts:
  - host: 203.0.113.10
    ssh: "root@203.0.113.10"
    ssh_opts: "-o BatchMode=yes -o ConnectTimeout=12 -o StrictHostKeyChecking=accept-new"
    # optional per-host overrides: root_folder_id / auth_mode / config_dir
  # - host: <add the rest of your servers here>

alerts:
  # Options for the separate alert helper; the runtime does not dispatch alerts automatically.
  discord: true
  relay: "~/.local/relay.py"  # a relay taking: send --stream infra --text <msg>
                              # leave unset to use $BOX_RCLONE_BINDER_RELAY, then a
                              # simple notifier at $BOX_RCLONE_BINDER_NOTIFIER
  on_recovered: INFO          # classification for callers of the alert helper
  on_heal_failed: CRITICAL    # classification for callers of the alert helper
  on_drift: WARN              # cross-host structure drift
  jitter_sec: 30              # helper option; does not schedule runtime retries
''',
        'secrets.env.example': '''# Generated by tools/make_fixtures.py; synthetic example only.
# Fill a chmod-600 file outside the public repository, such as /etc/box-binder/runtime.env.
# Real values belong in private storage; private versioned backups are allowed.
#
# JWT mode: jwt_config_ref resolves JSON content through the selected env/file source.
# The runtime installs a protected config.json and constructs the rclone environment.
#
# CCG mode: inject the client credentials from your secret backend at runtime:
# BOX_BINDER_CLIENT_ID=__from_secret_backend__
# BOX_BINDER_CLIENT_SECRET=__from_secret_backend__
# BOX_BINDER_ENTERPRISE_ID=__from_secret_backend__
#
# Encrypted-conf fallback only:
# BOX_BINDER_RCLONE_PASS=__from_secret_backend__
''',
    }


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--check', action='store_true')
    parser.add_argument('--out', type=Path, help='Generate the fixture basename into this directory.')
    args = parser.parse_args()
    outputs = {ROOT / 'skills/box-rclone-binder/config' / name: value.encode('utf-8')
               for name, value in config_example_sources().items()}
    outputs = {args.out / path.name if args.out else path: value for path, value in outputs.items()}
    if args.check:
        ok = all(path.is_file() and path.read_bytes() == expected for path, expected in outputs.items())
        print('Synthetic fixtures match generator.' if ok else 'Synthetic fixtures differ.')
        return 0 if ok else 1
    for path, expected in outputs.items():
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(expected)
    return 0


if __name__ == '__main__':
    raise SystemExit(main())
